-- First AI Capability Exam 2026 pilot: mixed-format bank and active instrument.
-- Historical attempts, results, payment orders, memberships, display IDs and QR routes are preserved.

alter table public.ai_assessment_items
  drop constraint if exists ai_assessment_items_item_type_check;

alter table public.ai_assessment_items
  add constraint ai_assessment_items_item_type_check
  check (item_type in ('objective', 'scenario', 'constructed', 'practical', 'choice', 'fill', 'numeric', 'code', 'open'));

insert into public.ai_assessment_instruments (
  id, framework_version, item_bank_version, scoring_version,
  instrument_type, title, description, item_count, status, config, published_at
)
values (
  $$first-ai-capability-exam-2026-v1$$,
  $$pacf-1.0.0$$,
  $$first-ai-exam-bank-1.0.0$$,
  $$first-ai-exam-scoring-1.0.0$$,
  'quick',
  $$第一届 AI 能力摸底考试（2026 试行卷）$$,
  $$从 54 道服务端候选题中分层抽取 30 道计分题与 2 道不计分主观题，覆盖六项 AI 能力与五种题型。$$,
  32,
  'active',
  $${"pool_size":54,"delivered_items":32,"scored_items":30,"unscored_open_items":2,"sampling":{"dimensions":["M","F","T","V","C","S"],"per_dimension":{"basic_choice":2,"scenario_choice":1,"fill_or_numeric":1,"technical":1}},"sections":["basic","scenario","fill","technical","open"],"evidence_grade":"screening"}$$::jsonb,
  now()
)
on conflict (id) do update
set framework_version = excluded.framework_version,
    item_bank_version = excluded.item_bank_version,
    scoring_version = excluded.scoring_version,
    title = excluded.title,
    description = excluded.description,
    item_count = excluded.item_count,
    status = excluded.status,
    config = excluded.config,
    published_at = coalesce(public.ai_assessment_instruments.published_at, excluded.published_at),
    retired_at = null,
    updated_at = now();

update public.ai_assessment_instruments
set status = 'retired', retired_at = coalesce(retired_at, now()), updated_at = now()
where instrument_type in ('quick', 'full', 'applied_lab')
  and id <> $$first-ai-capability-exam-2026-v1$$
  and status <> 'retired';

insert into public.ai_assessment_items (
  id, item_bank_version, competency_id, dimension_code, target_level,
  item_type, prompt_payload, scoring_payload, rationale, source_anchors,
  quick_eligible, status
)
values
($$AIX-M01-B1$$, $$first-ai-exam-bank-1.0.0$$, $$M01$$, $$M$$, 1, $$choice$$, $${"section":"basic","kind":"choice","prompt":"下面哪项最准确地区分“大语言模型”和“聊天产品”？","options":[{"id":"A","text":"模型负责生成，产品还组合界面、账户和工具"},{"id":"B","text":"模型保存账户，产品只负责展示生成的文字"},{"id":"C","text":"模型就是产品，二者只是不同公司的命名习惯"},{"id":"D","text":"模型负责联网，产品负责保存全部训练数据"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":0},{"id":"C","score":0},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$产品是模型及外围能力的组合。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-M02-B1$$, $$first-ai-exam-bank-1.0.0$$, $$M02$$, $$M$$, 2, $$choice$$, $${"section":"basic","kind":"choice","prompt":"为什么同一提示词前后可能得到不同答案？","options":[{"id":"A","text":"产品会随机删除部分用户输入以节省服务器成本"},{"id":"B","text":"模型按概率生成，输入上下文和采样也会影响输出"},{"id":"C","text":"模型每次回答后都会立即重新训练自己的参数"},{"id":"D","text":"只要网络速度发生变化，模型知识也会同步变化"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":3},{"id":"C","score":0},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$概率生成与上下文会造成输出波动。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-M03-B1$$, $$first-ai-exam-bank-1.0.0$$, $$M03$$, $$M$$, 2, $$choice$$, $${"section":"basic","kind":"choice","prompt":"关于上下文与长期记忆，哪项说法更准确？","options":[{"id":"A","text":"上传过的文件都会自动进入模型永久训练数据"},{"id":"B","text":"长期记忆只在当前消息生成期间临时起作用"},{"id":"C","text":"上下文服务当前任务，长期记忆需要另行保存和取用"},{"id":"D","text":"上下文和长期记忆都等同于模型原始训练知识"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":0},{"id":"C","score":3},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$上下文、记忆和训练知识必须区分。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-M04-S1$$, $$first-ai-exam-bank-1.0.0$$, $$M04$$, $$M$$, 3, $$choice$$, $${"section":"scenario","kind":"choice","prompt":"每月只处理20份固定格式表格，有人建议立刻搭多 Agent。你会先做什么？","options":[{"id":"A","text":"比较模板、脚本、单次模型和 Agent 的成本与错误率"},{"id":"B","text":"先搭多 Agent 原型，再根据展示效果决定是否保留"},{"id":"C","text":"先购买能力最强的模型，再讨论具体流程如何调整"},{"id":"D","text":"先让多个模型互相投票，再把多数答案作为最终结果"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":2},{"id":"C","score":0},{"id":"D","score":1}],"unscored":false}$$::jsonb, $$高水平选型从最小可靠方案和实测开始。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-M05-S1$$, $$first-ai-exam-bank-1.0.0$$, $$M05$$, $$M$$, 2, $$choice$$, $${"section":"scenario","kind":"choice","prompt":"AI 给出的建议造成业务损失，下面哪种责任理解更合适？","options":[{"id":"A","text":"供应商应承担责任，因为模型生成了原始建议"},{"id":"B","text":"发布者仍负有责任，因为采用和执行决定由人作出"},{"id":"C","text":"用户无需负责，因为页面已经标注内容由 AI 生成"},{"id":"D","text":"责任取决于价格，付费模型应自动承担更多责任"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":1},{"id":"B","score":3},{"id":"C","score":0},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$AI 不会接管采用者的最终责任。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-M03-F1$$, $$first-ai-exam-bank-1.0.0$$, $$M03$$, $$M$$, 1, $$fill$$, $${"section":"fill","kind":"fill","prompt":"当前任务中模型可直接使用的提示、历史消息和文件内容，通常统称为______。","placeholder":"请输入答案","unscored":false}$$::jsonb, $${"accepted_answers":["上下文","context","当前上下文"],"unscored":false}$$::jsonb, $$检查最基础的上下文概念。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-M01-F1$$, $$first-ai-exam-bank-1.0.0$$, $$M01$$, $$M$$, 2, $$fill$$, $${"section":"fill","kind":"fill","prompt":"由模型根据目标动态选择步骤并调用工具的系统，通常称为______。","placeholder":"请输入答案","unscored":false}$$::jsonb, $${"accepted_answers":["agent","智能体","ai agent","ai智能体"],"unscored":false}$$::jsonb, $$区分 Agent 与普通聊天或固定流程。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-M05-T1$$, $$first-ai-exam-bank-1.0.0$$, $$M05$$, $$M$$, 3, $$code$$, $${"section":"technical","kind":"code","prompt":"阅读下面的工具权限配置，最需要优先调整什么？","code":"tools:\n  email.read: all_mailboxes\n  payment.create: false\nlogging:\n  retention_days: 30","options":[{"id":"A","text":"把日志保留时间从30天调整为更短的7天"},{"id":"B","text":"把读取邮件权限改成只读取指定业务文件夹"},{"id":"C","text":"把模型名称从通用名称改为具体版本编号"},{"id":"D","text":"把执行结果的文字长度限制为一千字以内"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":1},{"id":"B","score":3},{"id":"C","score":2},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$最小权限优先于界面与输出细节。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-M01-O1$$, $$first-ai-exam-bank-1.0.0$$, $$M01$$, $$M$$, 3, $$open$$, $${"section":"open","kind":"open","prompt":"请向完全不懂技术的人解释：模型、Workflow 和 Agent 有什么不同，并各举一个例子。","placeholder":"请用 50–200 字作答","unscored":true}$$::jsonb, $${"unscored":true}$$::jsonb, $$观察概念能否被迁移和解释。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-F01-B1$$, $$first-ai-exam-bank-1.0.0$$, $$F01$$, $$F$$, 1, $$choice$$, $${"section":"basic","kind":"choice","prompt":"哪个请求最清楚地定义了预期结果？","options":[{"id":"A","text":"请认真帮我处理这份材料，尽量写得专业一些"},{"id":"B","text":"请扮演资深顾问，对材料进行全面深入的分析"},{"id":"C","text":"请根据附件，为新用户写一页可独立完成注册的说明"},{"id":"D","text":"请先自由发挥完成初稿，之后我再告诉你是否合适"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":1},{"id":"C","score":3},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$结果定义需要受众、产物和成功条件。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-F02-B1$$, $$first-ai-exam-bank-1.0.0$$, $$F02$$, $$F$$, 2, $$choice$$, $${"section":"basic","kind":"choice","prompt":"复杂任务拆解时，哪项原则最有帮助？","options":[{"id":"A","text":"按照每一步文字数量相同的方式平均拆分任务"},{"id":"B","text":"按照可验证中间产物和前后依赖关系拆分任务"},{"id":"C","text":"按照可用模型数量拆分，让每个模型负责一个部分"},{"id":"D","text":"按照操作人员数量拆分，避免同一个人重复检查"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":3},{"id":"C","score":1},{"id":"D","score":2}],"unscored":false}$$::jsonb, $$拆解应围绕依赖与可验证产物。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-F05-B1$$, $$first-ai-exam-bank-1.0.0$$, $$F05$$, $$F$$, 2, $$choice$$, $${"section":"basic","kind":"choice","prompt":"下面哪项最接近可执行的验收标准？","options":[{"id":"A","text":"整体读起来足够高级，能给负责人留下深刻印象"},{"id":"B","text":"结构完整、语言顺畅，并尽量覆盖更多相关信息"},{"id":"C","text":"一页内覆盖问题、证据和下一步，数字均可追溯"},{"id":"D","text":"使用统一模板和品牌颜色，避免出现明显排版问题"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":0},{"id":"B","score":1},{"id":"C","score":3},{"id":"D","score":2}],"unscored":false}$$::jsonb, $$验收标准应可明确判定且包含关键质量条件。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-F03-S1$$, $$first-ai-exam-bank-1.0.0$$, $$F03$$, $$F$$, 2, $$choice$$, $${"section":"scenario","kind":"choice","prompt":"AI 写出的品牌文案很通用，下一轮最值得补充什么？","options":[{"id":"A","text":"真实受众、品牌主张、素材、禁用表达和正反例"},{"id":"B","text":"更多角色称号、情绪词语、感叹号和流行表达"},{"id":"C","text":"更高随机性、更长输出长度和更多候选文案数量"},{"id":"D","text":"更多同行文章、热门标题和未经筛选的历史聊天"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":0},{"id":"C","score":1},{"id":"D","score":2}],"unscored":false}$$::jsonb, $$真实材料和边界比角色咒语更有效。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-F04-S1$$, $$first-ai-exam-bank-1.0.0$$, $$F04$$, $$F$$, 3, $$choice$$, $${"section":"scenario","kind":"choice","prompt":"长对话已经多次偏离目标，最稳妥的处理方式是什么？","options":[{"id":"A","text":"继续在原对话补充要求，保留模型已经生成的全部内容"},{"id":"B","text":"让模型自己回顾错误，再直接生成最终版本并立即提交"},{"id":"C","text":"整理目标、状态和未决问题，在新会话中用摘要重新开始"},{"id":"D","text":"把历史对话完整复制给另一个模型，让它判断谁更可靠"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":1},{"id":"B","score":2},{"id":"C","score":3},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$状态摘要和重启比无限追加更可靠。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-F05-F1$$, $$first-ai-exam-bank-1.0.0$$, $$F05$$, $$F$$, 1, $$fill$$, $${"section":"fill","kind":"fill","prompt":"在生成前约定准确性、格式、受众和通过条件，这组要求叫作______。","placeholder":"请输入答案","unscored":false}$$::jsonb, $${"accepted_answers":["验收标准","验收条件","acceptance criteria","通过标准"],"unscored":false}$$::jsonb, $$检查验收概念。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
