($$AIX-F01-O1$$, $$first-ai-exam-bank-1.0.0$$, $$F01$$, $$F$$, 3, $$open$$, $${"section":"open","kind":"open","prompt":"同事只写了“请帮我做好市场调研”。请把它改写成可执行任务，至少包含目标、材料、范围和验收标准。","placeholder":"请用 50–200 字作答","unscored":true}$$::jsonb, $${"unscored":true}$$::jsonb, $$观察任务契约表达能力。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-T01-B1$$, $$first-ai-exam-bank-1.0.0$$, $$T01$$, $$T$$, 1, $$choice$$, $${"section":"basic","kind":"choice","prompt":"环境变量最常见的用途是什么？","options":[{"id":"A","text":"把服务端密钥与公开代码分开保存并在运行时读取"},{"id":"B","text":"把网页样式与业务逻辑分开保存并在构建时合并"},{"id":"C","text":"把用户上传文件自动转成模型能够训练的数据格式"},{"id":"D","text":"把每次模型回答永久同步到所有访问设备的缓存"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":1},{"id":"C","score":0},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$环境变量常用于运行配置与敏感值隔离。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-T03-B1$$, $$first-ai-exam-bank-1.0.0$$, $$T03$$, $$T$$, 1, $$choice$$, $${"section":"basic","kind":"choice","prompt":"AI 回答里带有引用链接，下一步最合理的做法是什么？","options":[{"id":"A","text":"先检查链接能否打开，再核对原文是否支持对应主张"},{"id":"B","text":"先让另一个模型评价链接，再决定是否打开原始页面"},{"id":"C","text":"先把引用格式改成统一样式，再检查作者姓名是否完整"},{"id":"D","text":"先统计引用数量是否足够，再决定这份回答能否采用"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":1},{"id":"C","score":2},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$引用存在不等于引用已被核验。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-T04-B1$$, $$first-ai-exam-bank-1.0.0$$, $$T04$$, $$T$$, 2, $$choice$$, $${"section":"basic","kind":"choice","prompt":"处理访谈、图片和表格时，怎样组织工作区更可靠？","options":[{"id":"A","text":"按文件大小排序上传，让模型自行识别每份材料的作用"},{"id":"B","text":"建立清单、命名和版本规则，再按材料类型分批处理"},{"id":"C","text":"把所有材料压缩为一个文件，减少上传和下载操作次数"},{"id":"D","text":"先把图片转成截图，把表格转成文字后统一放进对话"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":1},{"id":"B","score":3},{"id":"C","score":0},{"id":"D","score":2}],"unscored":false}$$::jsonb, $$结构化工作区降低遗漏和版本混乱。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
