($$AIX-S04-B1$$, $$first-ai-exam-bank-1.0.0$$, $$S04$$, $$S$$, 3, $$choice$$, $${"section":"basic","kind":"choice","prompt":"一次 Demo 成功为什么不能证明系统可靠？","options":[{"id":"A","text":"演示环境通常网速更快，因此无法代表普通用户设备表现"},{"id":"B","text":"系统可能在不同输入、版本和异常条件下出现新的失败"},{"id":"C","text":"演示人员更熟悉操作，因此普通用户需要接受更多培训"},{"id":"D","text":"一次运行缺少宣传素材，因此无法证明产品具有市场价值"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":1},{"id":"B","score":3},{"id":"C","score":2},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$可靠性需要代表性测试和持续观测。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-S03-S1$$, $$first-ai-exam-bank-1.0.0$$, $$S03$$, $$S$$, 3, $$choice$$, $${"section":"scenario","kind":"choice","prompt":"任务规则稳定、分支已知且错误代价高，应优先选择什么？","options":[{"id":"A","text":"固定 Workflow，在必要节点加入模型判断和人工审批"},{"id":"B","text":"自主 Agent，让模型根据每次输入自由重新规划步骤"},{"id":"C","text":"多 Agent 协商，通过多数投票决定每一步如何执行"},{"id":"D","text":"单次聊天，把全部材料提交后要求模型一次完成任务"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":3},{"id":"B","score":2},{"id":"C","score":1},{"id":"D","score":0}],"unscored":false}$$::jsonb, $$稳定高风险任务更适合受控工作流。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-S05-S1$$, $$first-ai-exam-bank-1.0.0$$, $$S05$$, $$S$$, 4, $$choice$$, $${"section":"scenario","kind":"choice","prompt":"团队有20个AI用例提案但只能支持5个，应怎样选择？","options":[{"id":"A","text":"按提交时间排序，优先支持最早提出并已准备演示的项目"},{"id":"B","text":"按价值、风险、准备度和学习价值排序，并设停止条件"},{"id":"C","text":"按技术复杂度排序，优先建设最能展示模型能力的项目"},{"id":"D","text":"按部门规模排序，优先满足使用人数最多部门的全部需求"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":1},{"id":"B","score":3},{"id":"C","score":0},{"id":"D","score":2}],"unscored":false}$$::jsonb, $$组织采用需要组合管理和停止机制。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-S02-F1$$, $$first-ai-exam-bank-1.0.0$$, $$S02$$, $$S$$, 2, $$fill$$, $${"section":"fill","kind":"fill","prompt":"支付回调可能重复到达。让相同请求重复执行仍只产生一次权益，这种设计叫作______。","placeholder":"请输入答案","unscored":false}$$::jsonb, $${"accepted_answers":["幂等","幂等性","idempotency","idempotent"],"unscored":false}$$::jsonb, $$检查工作流幂等概念。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-S02-F2$$, $$first-ai-exam-bank-1.0.0$$, $$S02$$, $$S$$, 2, $$fill$$, $${"section":"fill","kind":"fill","prompt":"系统失败时回到安全、可人工处理状态的设计，通常称为______或降级。","placeholder":"请输入答案","unscored":false}$$::jsonb, $${"accepted_answers":["回退","fallback","故障回退","安全回退"],"unscored":false}$$::jsonb, $$检查失败恢复概念。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-S02-T1$$, $$first-ai-exam-bank-1.0.0$$, $$S02$$, $$S$$, 3, $$code$$, $${"section":"technical","kind":"code","prompt":"这段订单处理流程最明显缺少什么？","code":"async function onPaid(order) {\n  await grantMembership(order.userId);\n  await sendWelcomeMessage(order.userId);\n}","options":[{"id":"A","text":"支付成功页面的动画、颜色和完成提示文案"},{"id":"B","text":"订单唯一性与幂等检查，避免重复发放会员权益"},{"id":"C","text":"更多支付渠道之间的价格比较和自动推荐逻辑"},{"id":"D","text":"第二个模型对用户身份和支付意愿的独立判断"}],"unscored":false}$$::jsonb, $${"option_scores":[{"id":"A","score":1},{"id":"B","score":3},{"id":"C","score":0},{"id":"D","score":2}],"unscored":false}$$::jsonb, $$外部回调必须按唯一订单幂等处理。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active'),
($$AIX-S02-O1$$, $$first-ai-exam-bank-1.0.0$$, $$S02$$, $$S$$, 4, $$open$$, $${"section":"open","kind":"open","prompt":"请为“每周收集三个渠道的客户反馈并生成产品待办”设计流程，说明输入、步骤、人工检查、异常处理和效果指标。","placeholder":"请用 50–200 字作答","unscored":true}$$::jsonb, $${"unscored":true}$$::jsonb, $$综合观察流程和可靠性设计。$$, array['first-ai-exam-2026-pilot']::text[], true, 'active')
on conflict (id) do update
set item_bank_version = excluded.item_bank_version,
    competency_id = excluded.competency_id,
    dimension_code = excluded.dimension_code,
    target_level = excluded.target_level,
    item_type = excluded.item_type,
    prompt_payload = excluded.prompt_payload,
    scoring_payload = excluded.scoring_payload,
    rationale = excluded.rationale,
    source_anchors = excluded.source_anchors,
    quick_eligible = excluded.quick_eligible,
    status = excluded.status,
    updated_at = now();

comment on constraint ai_assessment_items_item_type_check on public.ai_assessment_items is
  'Supports legacy PACF rows plus the mixed-format First AI Exam item bank.';
